/// <summary>
/// MPJ_1918 - kscerri - 16/03/2021
/// Participant provider class extending <c>WorkflowParticipantProvider_Expend</c> uses dimension value to find cost 
/// center owner.
/// </summary>
public class METPurchReqLineWFParticipantProviderExpend extends WorkflowParticipantProvider_Expend
{
    const str owner = METConstants::WorkflowApprovalCostCenterOwner;

}

Method.Source:
/// <summary>
/// MPJ_1918 - kscerri - 16/03/2021
/// Document type is of type purchReq
/// </summary>
/// <returns>Document type purchReq</returns>
public WorkflowParticipantExpenDocumentType documentType()
{
    return WorkflowParticipantExpenDocumentType::PurchReq;
}

    /// <summary>
    /// MPJ_1918 - kscerri - 16/03/2021
    /// Adds "Cost Center owner" in workflow setup
    /// </summary>
    /// <returns>tokenlist</returns>
    public WorkflowParticipantTokenList getParticipantTokens()
    {
        WorkflowParticipantTokenList tokenList = WorkflowParticipantTokenList::construct();

        tokenList = super();
        tokenList.add(owner, METConstants::WorkflowApprovalCostCenterOwner);
        return tokenList;
    }

    /// <summary>
    /// MPJ_1918 - kscerri - 16/03/2021
    /// Finds the cost center owner from the purchreqline record and adds it to the user list
    /// </summary>
    /// <param name = "_context">context</param>
    /// <param name = "_participantTokenName">participantTokenName</param>
    /// <returns>UserList</returns>
    public WorkflowUserList resolve(WorkflowContext          _context,
                                    WorkflowParticipantToken _participantTokenName)
    {
        WorkflowUserList                userList = WorkflowUserList::construct();
        PurchReqLine                    purchReqLine = this.getPurchReqLineFromContext(_context);

        DimensionAttributeValueSetItem  dimensionAttributeValueSetItem;
        DimensionAttributeValue         dimensionAttributeValue;
        DimensionAttribute              dimensionAttribute;
        HcmWorker                       hcmWorker;
        DirPersonUser                   personUser;

        if (purchReqLine)
        {
            select firstonly User from personUser
                exists join dimensionAttribute
                    where dimensionAttribute.name == METConstants::costCenter
                exists join DimensionAttributeValueSetItem
                    where DimensionAttributeValueSetItem.DimensionAttributeValueSet == purchReqLine.DefaultDimension
                exists join dimensionAttributeValue
                    where dimensionAttributeValue.RecId == DimensionAttributeValueSetItem.dimensionAttributeValue
                       && dimensionAttributeValue.dimensionAttribute == dimensionAttribute.Recid
                exists join hcmWorker
                    where dimensionAttributeValue.owner == hcmWorker.Recid
                      &&  personUser.PersonParty == hcmWorker.Person;

            if (personUser)
            {
                userList.add(personUser.User);
            }
        }
        
        return userList;
    }

    /// <summary>
    /// MPJ_1918 - kscerri - 16/03/2021
    /// Finds the purchReqLine buffer
    /// </summary>
    /// <param name = "_context">workflowContext</param>
    /// <returns>Table buffer</returns>
    private PurchReqLine getPurchReqLineFromContext(WorkflowContext _context)
    {
        PurchReqLine purchReqLine;

        if (_context.parmTableId() == tableNum(PurchReqLine))
        {
            purchReqLine = PurchReqLine::find(_context.parmRecId());
        }

        return purchReqLine;
    }

/// <summary>
/// MPJ_1918 - kscerri - 16/03/2021
/// Checks the table names required
/// </summary>
/// <param name = "_context">WorkflowContext</param>
/// <returns>boolean</returns>
private boolean doesContextHaveExpectedTable(WorkflowContext _context)
{
    return _context.parmTableId() == tableNum(PurchReqLine) || _context.parmTableId() == tableNum(PurchReqTable);
}

/// <summary>
/// MPJ_1918 - kscerri - 16/03/2021
/// Constructor
/// </summary>
/// <returns>new constructor</returns>
public static METPurchReqLineWFParticipantProviderExpend construct()
{
    return new METPurchReqLineWFParticipantProviderExpend();
}
